import { describe, test, expect, vi } from 'vitest';
import { selectProductListCard, selectGalleryImages, selectSizeChipValues } from './productListCardMapper';

const formatPrice = vi.fn((amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`);
const buildUrl = (path: string) => path;

const baseHit = {
  productId: 'prod-1',
  productName: 'Natura Mini Dress',
  price: 595,
  currency: 'USD',
  image: { link: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
};

describe('selectProductListCard', () => {
  test('returns null when the hit has no product name', () => {
    expect(selectProductListCard({ ...baseHit, productName: undefined }, formatPrice, buildUrl)).toBeNull();
  });

  test('returns null when the hit has no usable image', () => {
    expect(selectProductListCard({ ...baseHit, image: undefined }, formatPrice, buildUrl)).toBeNull();
  });

  test('maps a real hit to plp ZimmProductCardProps', () => {
    const result = selectProductListCard(baseHit, formatPrice, buildUrl);
    expect(result).toEqual({
      id: 'prod-1',
      href: '/product/prod-1',
      name: 'Natura Mini Dress',
      headingLevel: 'h3',
      primaryImage: { src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
      images: undefined,
      currentPrice: 'USD 595.00',
      originalPrice: undefined,
      isUnavailable: false,
      badge: undefined,
      variation: 'plp',
      sizeChipValues: [],
    });
  });

  test('uses disBaseLink over link when both are present', () => {
    const hit = { ...baseHit, image: { link: 'fallback.jpg', disBaseLink: 'preferred.jpg', alt: 'x' } };
    expect(selectProductListCard(hit, formatPrice, buildUrl)?.primaryImage.src).toBe('preferred.jpg');
  });

  test('omits currentPrice when price is not a number', () => {
    const hit = { ...baseHit, price: undefined };
    expect(selectProductListCard(hit, formatPrice, buildUrl)?.currentPrice).toBeUndefined();
  });

  test('marks isUnavailable true when orderable is false', () => {
    expect(selectProductListCard({ ...baseHit, orderable: false }, formatPrice, buildUrl)?.isUnavailable).toBe(true);
  });

  test('maps the single highest-priority badge when c_productBadges is present', () => {
    const hit = { ...baseHit, c_productBadges: [{ productBadge: 'Runway' }, { productBadge: 'New In' }] };
    expect(selectProductListCard(hit, formatPrice, buildUrl)?.badge).toBe('Runway');
  });

  test('leaves badge undefined when c_productBadges is absent', () => {
    expect(selectProductListCard(baseHit, formatPrice, buildUrl)?.badge).toBeUndefined();
  });

  // Regression coverage for the regional-link bug: the PDP href must be run through the caller's
  // buildUrl() so it carries the current site/locale prefix — see
  // overrides/app/components/ui-kits/atoms/zimmNavItem/index.tsx's own fix for the same class of
  // bug (an unprefixed href always falls back to the default site on navigation).
  test('runs the product href through buildUrl() to carry the current site/locale prefix', () => {
    const regionalBuildUrl = (path: string) => `/uk${path}`;

    expect(selectProductListCard(baseHit, formatPrice, regionalBuildUrl)?.href).toBe('/uk/product/prod-1');
  });
});

describe('selectGalleryImages', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...baseHit, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when every group has only 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        { viewType: 'swatch', images: [{ link: 'b.jpg' }] },
      ],
    };
    expect(selectGalleryImages(hit)).toBeUndefined();
  });

  test('picks the image group with the most images', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        {
          viewType: 'large',
          images: [
            { link: 'b1.jpg', alt: 'front' },
            { link: 'b2.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: 'b1.jpg', alt: 'front' },
      { src: 'b2.jpg', alt: 'back' },
    ]);
  });
});

describe('selectSizeChipValues', () => {
  test('returns an empty array when there is no size variation attribute', () => {
    expect(selectSizeChipValues({ ...baseHit, variationAttributes: undefined })).toEqual([]);
  });

  test('maps size attribute values to chip values, disabled from orderable', () => {
    const hit = {
      ...baseHit,
      variationAttributes: [
        {
          id: 'size',
          name: 'Size',
          values: [
            { value: 'xs', name: 'XS', orderable: true },
            { value: 's', name: 'S', orderable: false },
          ],
        },
        { id: 'color', name: 'Colour', values: [{ value: 'black', name: 'Black', orderable: true }] },
      ],
    };
    expect(selectSizeChipValues(hit)).toEqual([
      { value: 'xs', label: 'XS', isDisabled: false },
      { value: 's', label: 'S', isDisabled: true },
    ]);
  });

  test('falls back to the raw value as label when name is missing', () => {
    const hit = {
      ...baseHit,
      variationAttributes: [{ id: 'size', values: [{ value: 'm', orderable: true }] }],
    };
    expect(selectSizeChipValues(hit)).toEqual([{ value: 'm', label: 'm', isDisabled: false }]);
  });
});

// constant
import {
  API_ERROR_MESSAGE,
  EINSTEIN_RECOMMENDERS,
  MAX_CACHE_AGE,
  TOAST_ACTION_VIEW_WISHLIST,
  TOAST_MESSAGE_ADDED_TO_WISHLIST,
  TOAST_MESSAGE_ALREADY_IN_WISHLIST,
  STALE_WHILE_REVALIDATE,
} from '@salesforce/retail-react-app/app/constants';
import { rebuildPathWithParams, productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import { useHistory, useLocation, useParams } from 'react-router-dom';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';

// SFCC-91 — colour swatches (rendered inside ProductView via renderVariationAttribute).
// Lazy-loaded so the swatch group's chunk is deferred until React renders it, keeping it
// off the critical path for LCP.
const ZimmColourSwatchGroup = React.lazy(() => import('../../components/ui-kits/molecules/zimmColourSwatchGroup'));

/** Frontend-enforced limit (SFCC-196). SFCC has no platform max-order-quantity field. */
const MAX_PURCHASE_QUANTITY = 3;

/*
 * `@salesforce/retail-react-app` ships no TypeScript types (see
 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
 * subpaths), so the product / variant / category values this page threads between base
 * hooks and base components have no compile-time shape *from that package*. But the shapes
 * themselves are `commerce-sdk-isomorphic`'s, and it does export them as
 * `ShopperProductsTypes.Product` / `.Variant` / `.Category` — so these aliases are a
 * deliberate temporary gap, not proof that no type is available, and AGENTS.md's Type
 * Definitions rule says to import those directly. Deferred to a follow-up only because the
 * substitution also clears three `no-explicit-any` warnings, moving a lint count this branch
 * holds as an invariant. See the same note in `components/product-view/index.tsx`.
 */
type SfccProduct = any;
type SfccVariant = any;
type SfccCategory = any;

/*
